import { test, expect } from "@playwright/test";
import { mkdir, mkdtemp, readFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { join, resolve } from "node:path";
import { configuration, createService, startServer } from "../../server.mjs";

const source = process.env.NIXTLA_E2E_MODEL_RUN;
let service, server, workspace, run, original, series, modelCount, initialForecast, mstlForecast, savedModel, timeline;
const hash = value => createHash("sha256").update(value).digest("hex");
const display = value => (Number(value) / 1e9).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
test.beforeAll(async () => {
  if (!source) return;
  if (!process.env.NIXTLA_E2E_OUTPUT) throw new Error("NIXTLA_E2E_OUTPUT must be a disposable artifact directory.");
  await mkdir(process.env.NIXTLA_E2E_OUTPUT, { recursive: true });
  workspace = await mkdtemp(join(resolve(process.env.NIXTLA_E2E_OUTPUT), "model-ux-"));
  original = hash(await readFile(join(source, "forecast.csv")));
  const { runtime, contract } = await configuration();
  service = createService({ workspace, python: runtime.python, contract });
  await service.call("initialize");
  run = await service.call("import_run", { path: resolve(source), name: "Saved model exploration" });
  const view = await service.call("view", { runId: run.id });
  series = view.series[0];
  savedModel = view.rows.find(row => String(row.unique_id) === series).model;
  const history = await service.call("view", { runId: run.id, kind: "history", series });
  const start = history.rows.map(row => row.ds.slice(0, 10)).sort()[0];
  const end = view.rows.filter(row => String(row.unique_id) === series).map(row => row.ds.slice(0, 10)).sort().at(-1);
  timeline = new RegExp(`^Forecast timeline, ${start} to ${end};`);
  const future = await service.call("evidence", { runId: run.id, name: "appendix/forecast_long.csv", series });
  modelCount = future.models.length;
  mstlForecast = future.rows.find(row => row.model === "MSTL").yhat;
  initialForecast = future.rows.filter(row => row.model === "AutoARIMA_MSTLFeatures")
    .sort((a, b) => a.ds.localeCompare(b.ds)).at(-1).yhat;
  server = await startServer({ workspace, service, handoff: async () => {} });
});
test.afterAll(async () => { await server?.close(); await service?.close(); });
test.beforeEach(async () => {
  if (!service) return;
  const catalog = await service.call("catalog");
  await service.call("save_state", { expectedRevision: catalog.revision, state: {
    documents: [{ id: "models", runId: run.id, title: "Saved model exploration", series, view: "Forecast",
      analysis: { previewModel: "AutoARIMA_MSTLFeatures", models: ["*"], scale: "billions" } }],
    activeId: "models", theme: "light",
  } });
});

test("saved candidate paths: search, focus, compare, replay, persist and unclipped hover", async ({ page }) => {
  test.skip(!source, "Set NIXTLA_E2E_MODEL_RUN to a synthetic tournament with MSTL future-only evidence. No fits are performed.");
  test.setTimeout(240000);
  const errors = [], mutations = [];
  page.on("pageerror", error => errors.push(error.message));
  page.on("request", request => {
    const body = request.url().endsWith("/api") ? request.postDataJSON() : null;
    if (body && ["start_job", "adopt_blend", "import_run"].includes(body.operation)) mutations.push(body);
  });
  await page.goto(server.url);
  const browser = page.getByRole("region", { name: "Model browser", exact: true });
  const legend = page.getByRole("list", { name: "Chart series", exact: true });
  await expect(browser).toContainText(`${modelCount} in this run`);
  await expect(browser.locator(".focused-model")).toContainText(display(initialForecast));
  await expect(legend.locator("li")).toHaveCount(2);
  await expect(browser.getByRole("button", { name: "Focus one", exact: true })).toHaveAttribute("aria-pressed", "true");
  await page.getByLabel("Find a model", { exact: true }).fill("mstl");
  await expect(browser.getByRole("button", { name: /^Focus / })).toHaveCount(4); // Focus one plus the three MSTL variants.
  await browser.getByRole("button", { name: "Focus MSTL", exact: true }).focus();
  await page.keyboard.press("Enter");
  await expect(page.getByRole("region", { name: "Forecast values", exact: true })).toContainText(display(mstlForecast));
  await expect(browser.locator(".focused-model")).toContainText("No saved tournament score");
  await browser.getByRole("button", { name: "Next model", exact: true }).click();
  await expect(browser.locator(".focused-model")).toContainText("MSTL_AutoARIMA");
  await browser.getByRole("button", { name: "Previous model", exact: true }).click();
  await expect(browser.locator(".focused-model strong")).toHaveText("MSTL");
  await browser.getByLabel("Compare AutoARIMA_MSTLFeatures", { exact: true }).check();
  await expect(browser.locator(".model-shortlist > div")).toHaveCount(2);
  await page.getByLabel("Find a model", { exact: true }).fill("AutoARIMA");
  await browser.getByLabel("Compare AutoARIMA", { exact: true }).check();
  await browser.getByRole("button", { name: "Emphasize AutoARIMA_MSTLFeatures", exact: true }).click();
  await expect(legend).toContainText("AutoARIMA_MSTLFeatures");
  await expect(legend.locator("li")).toHaveCount(4);
  await page.getByRole("button", { name: "Models", exact: true }).click();
  await expect(page.locator("#model-race .chart-legend li")).toHaveCount(4);
  await expect(page.getByRole("region", { name: "Component tournament", exact: true }).locator("tbody tr")).not.toHaveCount(3);
  const search = page.getByLabel("Find a model", { exact: true });
  await search.fill("does-not-exist");
  await expect(browser).toContainText("No matching model in this run");
  await search.fill("Naive");
  await browser.getByLabel("Compare Naive", { exact: true }).check();
  await search.fill("Theta");
  await browser.getByLabel("Compare AutoTheta", { exact: true }).check();
  await expect(browser.locator(".model-shortlist > div")).toHaveCount(5);
  await expect(browser.getByLabel("Compare DynamicOptimizedTheta", { exact: true })).toBeDisabled();
  await browser.getByRole("button", { name: "Remove Naive from comparison", exact: true }).click();
  await expect(browser.locator(".model-shortlist > div")).toHaveCount(4);
  await expect(browser.getByLabel("Compare DynamicOptimizedTheta", { exact: true })).toBeEnabled();
  await search.fill("MSTL");
  await page.locator(".model-workspace").scrollIntoViewIfNeeded();
  await page.screenshot({ path: join(workspace, "models-desktop.png") });
  const chart = page.locator("#model-race .chart");
  await expect(chart).toHaveAttribute("aria-label", timeline);
  await expect(page.locator("#model-race .chart-legend li")).toHaveCount(5);
  await chart.scrollIntoViewIfNeeded();
  let box = await chart.boundingBox();
  await page.mouse.move(box.x + box.width * .3, box.y + box.height * .5);
  const tooltip = page.locator(".workbench-chart-tooltip").filter({ has: page.locator(".chart-tooltip-content") });
  await expect(tooltip).toBeVisible();
  await expect(tooltip).toContainText("Observed actuals");
  await expect(tooltip).not.toContainText("MSTL");
  await expect(tooltip.locator(".chart-tooltip-row")).toHaveCount(1);
  box = await chart.locator("canvas").boundingBox();
  await page.mouse.move(box.x + box.width * .90, box.y + box.height * .5);
  await expect(tooltip).toContainText("MSTL");
  await expect(async () => {
    const tooltipBox = await tooltip.boundingBox();
    expect(tooltipBox.x).toBeGreaterThanOrEqual(0);
    expect(tooltipBox.x + tooltipBox.width).toBeLessThanOrEqual(1440);
    expect(tooltipBox.y + tooltipBox.height).toBeLessThanOrEqual(1000);
  }).toPass({ timeout: 5000 });
  await page.setViewportSize({ width: 620, height: 900 });
  await page.getByRole("button", { name: "Toggle library", exact: true }).click();
  await page.getByLabel("Appearance").selectOption("dark");
  await page.locator(".model-workspace").scrollIntoViewIfNeeded();
  await page.screenshot({ path: join(workspace, "models-narrow-dark.png") });
  await chart.scrollIntoViewIfNeeded();
  box = await chart.boundingBox();
  await page.mouse.move(box.x + box.width * .86, box.y + box.height * .5);
  await expect(tooltip).toBeVisible();
  await expect(async () => {
    const narrowTooltip = await tooltip.boundingBox();
    expect(narrowTooltip.x).toBeGreaterThanOrEqual(0);
    expect(narrowTooltip.x + narrowTooltip.width).toBeLessThanOrEqual(620);
    expect(narrowTooltip.y + narrowTooltip.height).toBeLessThanOrEqual(900);
  }).toPass({ timeout: 5000 });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await page.screenshot({ path: join(workspace, "models-narrow-tooltip.png") });
  await page.setViewportSize({ width: 390, height: 844 });
  await search.fill("");
  await browser.scrollIntoViewIfNeeded();
  await page.screenshot({ path: join(workspace, "models-mobile.png") });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.getByLabel("Appearance").selectOption("light");
  await browser.getByRole("button", { name: "Focus AutoARIMA", exact: true }).click();
  await page.getByRole("button", { name: "Backtests", exact: true }).click();
  await expect(page.locator("#backtest-replay")).toHaveAttribute("aria-busy", "false");
  await expect(page.locator("#backtest-replay .chart-legend")).toContainText("AutoARIMA");
  const before = await page.getByLabel("Backtest origin", { exact: true }).inputValue();
  await page.getByRole("button", { name: "Previous window", exact: true }).click();
  await expect(page.getByLabel("Backtest origin", { exact: true })).not.toHaveValue(before);
  await expect(page.locator("#backtest-replay")).toHaveAttribute("aria-busy", "false");
  await page.getByLabel("Backtest interval", { exact: true }).selectOption("80");
  await browser.getByRole("button", { name: /^Compare ·/ }).click();
  await browser.getByRole("button", { name: "Emphasize MSTL", exact: true }).click();
  await expect(page.locator("#backtest-replay")).toHaveAttribute("aria-busy", "false");
  await expect(browser.locator(".focused-model strong")).toHaveText("MSTL");
  await expect(page.getByText("No saved backtest predictions for MSTL in this window. Other comparison paths remain visible; no model has been substituted.", { exact: true })).toBeVisible();
  await expect(page.locator("#backtest-replay .chart-legend")).toContainText("AutoARIMA");
  await expect(page.locator("#backtest-replay .chart-legend")).not.toContainText("Saved 80% interval");
  await expect(page.getByText("No saved 80% bounds exist for MSTL in this window. No interval has been synthesized.", { exact: true })).toBeVisible();
  await page.locator(".model-workspace").scrollIntoViewIfNeeded();
  await page.screenshot({ path: join(workspace, "backtest-missing-focus-desktop.png") });
  await page.setViewportSize({ width: 620, height: 900 });
  await page.locator("#backtest-replay").scrollIntoViewIfNeeded();
  await page.screenshot({ path: join(workspace, "backtest-missing-focus-narrow.png") });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.getByLabel("Find a model", { exact: true }).fill("MSTL");
  await browser.getByRole("button", { name: "Focus MSTL", exact: true }).click();
  await expect(page.getByText("No saved backtest windows are available for this series and model selection.", { exact: true })).toBeVisible();
  await page.getByRole("button", { name: "Forecast", exact: true }).click();
  await expect(page.getByRole("region", { name: "Forecast values", exact: true })).toContainText(display(mstlForecast));
  await expect.poll(async () => (await service.call("catalog")).state.documents[0].analysis.previewModel).toBe("MSTL");
  await page.reload();
  await expect(browser.locator(".focused-model strong")).toHaveText("MSTL");
  await browser.getByRole("button", { name: "Return to saved selection", exact: true }).click();
  await expect(browser.locator(".focused-model strong")).toHaveText(savedModel);
  await expect(page.getByRole("alert")).toHaveCount(0);
  expect(mutations).toEqual([]);
  expect(errors).toEqual([]);
  expect((await service.call("catalog")).jobs).toHaveLength(0);
  expect(hash(await readFile(join(source, "forecast.csv")))).toBe(original);
  console.log(`Model exploration screenshots: ${workspace}`);
});
